#include <string.h>

int main() {
    char p[105], a[105];
    if (scanf("%100s", p) != 1) return 0;
    if (scanf("%100s", a) != 1) return 0;

    int count_p[26] = {0};
    int count_a[26] = {0};

    for (int i = 0; p[i] != '\0'; i++) {
        count_p[p[i] - 'a']++;
    }

    for (int i = 0; a[i] != '\0'; i++) {
        if (a[i] >= 'a' && a[i] <= 'z') {
            count_a[a[i] - 'a']++;
        }
    }

    int possible = 1;
    for (int i = 0; i < 26; i++) {
        if (count_a[i] > count_p[i]) {
            possible = 0;
            break;
        }
    }

    if (possible) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
